// Generated from public/HSF_logo.webp (sips -s format png --resampleWidth 600).
// Embedded as a data URI so the PDF renderer works in Vercel's serverless
// bundle, where files in /public are not on the function's filesystem.
// @react-pdf/renderer cannot decode webp, hence the PNG copy.
export const HSF_LOGO_PNG_DATA_URI =
  'data:image/png;base64,';
